import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';
import { FiMapPin, FiPhone, FiUser, FiArrowLeft } from 'react-icons/fi';

const ProductDetail = () => {
    const { id } = useParams();
    const { user } = useAuth();
    const navigate = useNavigate();
    const [product, setProduct] = useState(null);
    const [loading, setLoading] = useState(true);
    const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);
    const [showContact, setShowContact] = useState(false);

    useEffect(() => {
        fetchProduct();
    }, [id]);

    const fetchProduct = async () => {
        try {
            const response = await api.get(`/products/${id}`);
            setProduct(response.data.product);
        } catch (error) {
            toast.error('Produto não encontrado');
            navigate('/');
        } finally {
            setLoading(false);
        }
    };

    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    const getContactMethodIcon = (method) => {
        if (method === 'whatsapp') return '💚 WhatsApp';
        if (method === 'call') return '📞 Ligação';
        return '💚 WhatsApp / 📞 Ligação';
    };

    const handleContact = () => {
        if (!user) {
            toast.error('Faça login para ver o contato');
            navigate('/login');
            return;
        }
        setShowContact(true);
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
            </div>
        );
    }

    if (!product) return null;

    const isOwner = user && product.sellerId === user.id;

    return (
        <div className="max-w-4xl mx-auto">
            <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-gray-600 hover:text-primary-600 mb-4">
                <FiArrowLeft /> Voltar
            </button>

            <div className="bg-white rounded-xl shadow-md overflow-hidden">
                <div className="md:flex">
                    {/* Coluna da Imagem */}
                    <div className="md:w-1/2 bg-gray-50">
                        <div className="h-80 flex items-center justify-center p-4">
                            {product.photos && product.photos.length > 0 ? (
                                <img 
                                    src={`http://localhost:3001${product.photos[currentPhotoIndex]}`} 
                                    alt={product.title} 
                                    className="max-w-full max-h-full object-contain" 
                                />
                            ) : (
                                <span className="text-6xl">{getCategoryIcon(product.category)}</span>
                            )}
                        </div>
                        
                        {/* Miniaturas */}
                        {product.photos && product.photos.length > 1 && (
                            <div className="flex gap-2 p-4 overflow-x-auto border-t">
                                {product.photos.map((photo, idx) => (
                                    <button
                                        key={idx}
                                        onClick={() => setCurrentPhotoIndex(idx)}
                                        className={`w-16 h-16 rounded-lg overflow-hidden border-2 ${
                                            currentPhotoIndex === idx ? 'border-primary-600' : 'border-gray-200'
                                        }`}
                                    >
                                        <img 
                                            src={`http://localhost:3001${photo}`} 
                                            alt={`Foto ${idx + 1}`} 
                                            className="w-full h-full object-cover" 
                                        />
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                    
                    {/* Coluna das Informações */}
                    <div className="md:w-1/2 p-6">
                        <h1 className="text-2xl font-bold text-gray-800 mb-2">{product.title}</h1>
                        
                        <div className="flex items-center gap-2 mb-3">
                            <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                                product.condition === 'novo' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'
                            }`}>
                                {product.condition === 'novo' ? 'Novo' : 'Semi-novo'}
                            </span>
                            <span className="text-sm text-gray-500">{product.category}</span>
                        </div>
                        
                        <p className="text-3xl font-bold text-primary-600 mb-4">
                            {product.price.toLocaleString()} Kz
                        </p>
                        
                        <div className="border-t border-gray-100 pt-4 mb-4">
                            <p className="text-gray-700 leading-relaxed">{product.description}</p>
                        </div>
                        
                        <div className="space-y-3 mb-6">
                            <div className="flex items-center text-gray-600">
                                <FiMapPin className="mr-2 text-gray-400" />
                                <span>{product.location}</span>
                            </div>
                            <div className="flex items-center text-gray-600">
                                <FiUser className="mr-2 text-gray-400" />
                                <span>Vendedor: {product.sellerName}</span>
                            </div>
                            <div className="text-sm text-gray-400">
                                👁️ {product.views || 0} visualizações
                            </div>
                        </div>
                        
                        {!isOwner && (
                            <>
                                {showContact ? (
                                    <div className="bg-green-50 p-4 rounded-lg border border-green-200">
                                        <div className="flex items-center gap-2 text-green-600 mb-2">
                                            <FiPhone className="text-green-500" />
                                            <span className="font-semibold">{getContactMethodIcon(product.contactMethod)}</span>
                                        </div>
                                        <p className="text-xl font-bold text-green-700 mb-1">{product.contactNumber}</p>
                                        {product.contactHours && (
                                            <p className="text-sm text-green-600">Horário: {product.contactHours}</p>
                                        )}
                                        <p className="text-xs text-green-500 mt-2">Clique no número para entrar em contato</p>
                                    </div>
                                ) : (
                                    <button
                                        onClick={handleContact}
                                        className="w-full bg-primary-600 text-white py-3 rounded-lg font-semibold hover:bg-primary-700 transition"
                                    >
                                        Ver número do vendedor
                                    </button>
                                )}
                            </>
                        )}
                        
                        {isOwner && (
                            <div className="bg-blue-50 p-4 rounded-lg border border-blue-200">
                                <p className="text-blue-600 font-semibold mb-2">📌 Este é seu anúncio</p>
                                <p className="text-sm text-blue-600">
                                    <strong>Contato:</strong> {getContactMethodIcon(product.contactMethod)}<br />
                                    <strong>Número:</strong> {product.contactNumber}
                                    {product.contactHours && <><br /><strong>Horário:</strong> {product.contactHours}</>}
                                </p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ProductDetail;
